using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;using UnityEditor;using UnityEngine;
public static class OpenRPGHouseWireStorageV668{
 [Serializable]public class Level{public int level,width,height,bytes;public string path;}
 [Serializable]public class Item{public string guid,folder;public Level[] levels;}
 [Serializable]public class Request{public string output,shader_path;public Item[] textures;}
 [Serializable]public class Row{public string guid,format,graphics_format,whole_path,whole_sha256;public Level[] levels;public bool native_decoded_mips_equal,restored_decoded_mips_equal,importer_restored_equal,meta_bytes_restored_equal;public string settings_before,settings_restored,error="";public int width,height,mip_count,whole_bytes,filter_mode,wrap_u,wrap_v,wrap_w,aniso;public float mip_bias;public Level[] mips;public bool settings_restored_equal,gpu_samples_bit_exact,private_readability_override;}
 [Serializable]public class Report{public string unity_version,graphics_api;public Row[] textures,rows;public bool full_import=false;}
 static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 static void Verify(Texture2D t,ComputeShader s,Item item){int k=s.FindKernel("CopyMip");if(t.mipmapCount!=item.levels.Length)throw new Exception("Mip count differs");foreach(var l in item.levels){using(var output=new ComputeBuffer(l.width*l.height,16)){s.SetTexture(k,"_Texture",t);s.SetBuffer(k,"_Output",output);s.SetInt("_Width",l.width);s.SetInt("_Height",l.height);s.SetInt("_Mip",l.level);s.Dispatch(k,(l.width+7)/8,(l.height+7)/8,1);var vectors=new Vector4[l.width*l.height];output.GetData(vectors);var bytes=new byte[vectors.Length*16];for(int i=0;i<vectors.Length;i++)for(int c=0;c<4;c++)Buffer.BlockCopy(BitConverter.GetBytes(vectors[i][c]),0,bytes,i*16+c*4,4);if(Hash(bytes)!=Hash(File.ReadAllBytes(l.path)))throw new Exception("Decoded native mip differs: "+item.guid+"/"+l.level);}}}
 public static void Export(){var args=Environment.GetCommandLineArgs();int a=Array.IndexOf(args,"--openrpg-manifest");if(a<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[a+1]));if(File.Exists(r.output)||r.textures.Length!=18)throw new Exception("Preserve evidence; 18 resources required");var shader=AssetDatabase.LoadAssetAtPath<ComputeShader>(r.shader_path);if(shader==null)throw new Exception("Owned mip probe missing");var rows=new List<Row>();
  foreach(var item in r.textures){string path=AssetDatabase.GUIDToAssetPath(item.guid);var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(t==null||importer==null)throw new Exception("Native texture absent");if(t.format!=TextureFormat.DXT1&&t.format!=TextureFormat.DXT5)throw new Exception("BC format required");
   var row=new Row{guid=item.guid,format=t.format.ToString(),graphics_format=t.graphicsFormat.ToString()};string json=EditorJsonUtility.ToJson(importer,true);bool readable=importer.isReadable;string meta=Path.GetFullPath(Path.Combine(Application.dataPath,"..",path+".meta"));byte[] metaBytes=File.ReadAllBytes(meta);
if(readable)throw new Exception("Wire protocol requires originally unreadable importer");
row.settings_before=json;row.width=t.width;row.height=t.height;row.mip_count=t.mipmapCount;
row.filter_mode=(int)t.filterMode;row.wrap_u=(int)t.wrapModeU;row.wrap_v=(int)t.wrapModeV;row.wrap_w=(int)t.wrapModeW;row.aniso=t.anisoLevel;row.mip_bias=t.mipMapBias;
row.private_readability_override=true;Verify(t,shader,item);Directory.CreateDirectory(item.folder);
   try{if(!readable){importer.isReadable=true;importer.SaveAndReimport();}t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(t.format.ToString()!=row.format||t.graphicsFormat.ToString()!=row.graphics_format)throw new Exception("Native format changed");Verify(t,shader,item);row.native_decoded_mips_equal=true;
    var whole=t.GetRawTextureData<byte>().ToArray();row.whole_path=Path.Combine(item.folder,"whole.native.bin");if(File.Exists(row.whole_path))throw new Exception("Preserve raw BC data");File.WriteAllBytes(row.whole_path,whole);row.whole_sha256=Hash(whole);var levels=new List<Level>();int bytesTotal=0;
    foreach(var l in item.levels){var data=t.GetPixelData<byte>(l.level).ToArray();int expected=Math.Max(1,(l.width+3)/4)*Math.Max(1,(l.height+3)/4)*(t.format==TextureFormat.DXT1?8:16);if(data.Length!=expected)throw new Exception("BC block size differs");string output=Path.Combine(item.folder,"mip-"+l.level+".native.bin");if(File.Exists(output))throw new Exception("Preserve BC mip");File.WriteAllBytes(output,data);bytesTotal+=data.Length;levels.Add(new Level{level=l.level,width=l.width,height=l.height,bytes=data.Length,path=output});}if(bytesTotal!=whole.Length)throw new Exception("BC storage coverage differs");row.levels=levels.ToArray();
   }finally{EditorJsonUtility.FromJsonOverwrite(json,importer);importer.isReadable=readable;importer.SaveAndReimport();File.WriteAllBytes(meta,metaBytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);importer=AssetImporter.GetAtPath(path) as TextureImporter;row.importer_restored_equal=EditorJsonUtility.ToJson(importer,true)==json;row.meta_bytes_restored_equal=Hash(File.ReadAllBytes(meta))==Hash(metaBytes);if(!row.importer_restored_equal||!row.meta_bytes_restored_equal)throw new Exception("Private importer restoration differs");}
   t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);Verify(t,shader,item);row.restored_decoded_mips_equal=true;
row.settings_restored=EditorJsonUtility.ToJson(importer,true);row.settings_restored_equal=row.importer_restored_equal;
row.gpu_samples_bit_exact=row.native_decoded_mips_equal&&row.restored_decoded_mips_equal;
row.mips=row.levels;row.whole_bytes=File.ReadAllBytes(row.whole_path).Length;rows.Add(row);
  }
  File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,graphics_api=SystemInfo.graphicsDeviceType.ToString(),textures=rows.ToArray(),rows=rows.ToArray()},true));
 }
}
